       double dLon = lon2 - lon1;
       double a = pow(sin(dLat / 2), 2) + cos(lat1) * cos(lat2) * pow(sin(dLon / 2), 2);
       double c = 2 * atan2(sqrt(a), sqrt(1 - a));
       double distance = R * c;
